import { Queue } from 'bullmq'
import IORedis from 'ioredis'

/**
 * BullMQ job queue enqueuer for the web service.
 *
 * The web service ONLY enqueues jobs — it never processes them.
 * Jobs are processed by the worker-jobs Railway service.
 *
 * Uses REDIS_PRIVATE_URL (Railway internal DNS) in production.
 */

let _connection: IORedis | null = null

function getConnection(): IORedis {
  if (!_connection) {
    const redisUrl = process.env.REDIS_PRIVATE_URL
    if (!redisUrl) {
      throw new Error('REDIS_PRIVATE_URL is not configured')
    }
    _connection = new IORedis(redisUrl, {
      // REQUIRED: BullMQ requires maxRetriesPerRequest to be null
      maxRetriesPerRequest: null,
      enableReadyCheck: false,
      lazyConnect: true,
    })
  }
  return _connection
}

let _queue: Queue | null = null

function getQueue(): Queue {
  if (!_queue) {
    _queue = new Queue('inkos-jobs', {
      connection: getConnection(),
      defaultJobOptions: {
        attempts: 3,
        backoff: {
          type: 'exponential',
          delay: 2000,
        },
        removeOnComplete: { count: 1000, age: 86400 },
        removeOnFail: { count: 5000 },
      },
    })
  }
  return _queue
}

/**
 * Job payload type map — add new job types here as sprints add features.
 */
export interface JobPayloads {
  'send-email': {
    to: string
    template: string
    data: Record<string, unknown>
  }
  'generate-consent-pdf': {
    submission_id: string
    studio_id: string
  }
  'process-ai-design': {
    requestId: string
    studioId: string
  }
  'send-booking-reminder': {
    bookingId: string
    reminderType: 'day_before' | 'hour_before'
  }
  'generate-payroll': {
    studioId: string
    periodStart: string
    periodEnd: string
  }
  'sync-calendar': {
    studioId: string
    artistId: string
  }
  'generate-1099k': {
    studioId: string
    artistId: string
    year: number
  }
  'generate-tax-form-pdf': {
    form_id: string
    studio_id: string
  }
  'send-tax-form': {
    form_id: string
    studio_id: string
    sent_by: string
  }
  'send-low-stock-alert': {
    studio_id: string
    item_id: string
    item_name: string
    current_stock: number
    min_threshold: number
    studio_owner_email: string
  }
  // Sprint 11 — Marketing & Integrations
  'send-marketing-campaign': {
    campaignId: string
    studioId: string
    triggeredBy: string
  }
  'send-review-request': {
    bookingId: string
    studioId: string
    clientEmail: string
    googleReviewUrl: string
  }
  'send-birthday-greeting': {
    clientId: string
    studioId: string
  }
  'send-win-back': {
    clientId: string
    studioId: string
    daysSinceLastVisit: number
  }
  'send-referral-welcome': {
    referralRedemptionId: string
    studioId: string
  }
}

/**
 * Type-safe job enqueue helper.
 */
export async function enqueueJob<K extends keyof JobPayloads>(
  name: K,
  data: JobPayloads[K],
  options?: { delay?: number; priority?: number }
): Promise<string | undefined> {
  const job = await getQueue().add(name, data, options)
  return job.id
}

