#!/usr/bin/env tsx
/**
 * Vega Visual Review Script
 *
 * Captures screenshots of every authenticated and public route at
 * 4 breakpoints × 2 color modes for visual review.
 *
 * Usage:
 *   pnpm vega:review
 *   pnpm vega:review --url https://preview-xxx.railway.app
 *
 * Output: .vega-screenshots/[timestamp]/
 */
import { chromium, type Browser, type BrowserContext } from '@playwright/test'
import fs from 'node:fs/promises'
import path from 'node:path'

const VIEWPORTS = [
  { name: 'mobile', width: 390, height: 844 },
  { name: 'tablet', width: 768, height: 1024 },
  { name: 'desktop', width: 1280, height: 800 },
  { name: 'wide', width: 1920, height: 1080 },
] as const

const MODES = ['light', 'dark'] as const

/**
 * Routes to review — updated each sprint as routes ship.
 */
const ROUTES: Array<{ path: string; name: string; auth: boolean }> = [
  { path: '/login', name: 'login', auth: false },
  { path: '/signup', name: 'signup', auth: false },
  { path: '/forgot-password', name: 'forgot-password', auth: false },
  { path: '/dashboard', name: 'dashboard', auth: true },
  { path: '/settings', name: 'settings', auth: true },
  // Sprint 2+: calendar, appointments, clients, etc.
]

async function captureRoute(
  context: BrowserContext,
  baseUrl: string,
  route: (typeof ROUTES)[number],
  viewport: (typeof VIEWPORTS)[number],
  mode: (typeof MODES)[number],
  outDir: string
): Promise<void> {
  const page = await context.newPage()
  try {
    await page.goto(`${baseUrl}${route.path}`, { waitUntil: 'networkidle' })
    await page.waitForTimeout(500)

    const safeName = route.name.replace(/\//g, '-')
    const filename = `${safeName}_${viewport.name}_${mode}.png`
    await page.screenshot({ path: path.join(outDir, filename), fullPage: true })
    process.stdout.write(`  ok  ${route.path} @ ${viewport.name}/${mode}\n`)
  } catch (err) {
    process.stderr.write(`  fail  ${route.path} @ ${viewport.name}/${mode}: ${String(err)}\n`)
  } finally {
    await page.close()
  }
}

async function main() {
  const args = process.argv.slice(2)
  const urlFlag = args.indexOf('--url')
  const baseUrl =
    urlFlag !== -1 && args[urlFlag + 1]
      ? (args[urlFlag + 1] as string)
      : (process.env['NEXT_PUBLIC_APP_URL'] ?? 'http://localhost:3000')

  const timestamp = new Date().toISOString().replace(/[:.]/g, '-').slice(0, 19)
  const outDir = path.join('.vega-screenshots', timestamp)
  await fs.mkdir(outDir, { recursive: true })

  process.stdout.write(`Vega review: ${baseUrl}\nOutput: ${outDir}\n\n`)

  const browser: Browser = await chromium.launch()

  for (const route of ROUTES) {
    for (const viewport of VIEWPORTS) {
      for (const mode of MODES) {
        const context = await browser.newContext({
          viewport: { width: viewport.width, height: viewport.height },
          colorScheme: mode,
        })
        await captureRoute(context, baseUrl, route, viewport, mode, outDir)
        await context.close()
      }
    }
  }

  await browser.close()
  process.stdout.write(`\nScreenshots saved: ${outDir}\n`)
}

main().catch((err) => {
  process.stderr.write(`vega-review failed: ${String(err)}\n`)
  process.exit(1)
})

